import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#5
it('passes valid input and extra properties unchanged to the executor', async () => {
  const registry = new ToolRegistry();
  const executor = jest.fn(async () => 'sunny');
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}}},
    executor
  );
  const input = {location: 'Paris', extra: 'value'};
  await registry.execute('weather', input);
  expect(executor).toHaveBeenCalledTimes(1);
  expect(executor).toHaveBeenCalledWith(input, undefined);
});
EOF
